    :type="popupType"
    :data="selectedRow"
    @close="closePopup"
    @save="handleSave"
    @delete="handleDelete"
  />
</template>

<script>
// @ is an alias to /src
import rolePopup from "@/components/dashboard/popus/rolePopup.vue";
import SvgIcon from "@/components/SvgIcon.vue";

export default {
  name: "addBanners",
  components: {
    rolePopup,
    SvgIcon,
  },
  data() {
    return {
      filter: "",
      rows: [
        {
          code: 1,
          name: "احمد محمد",
          email: "ahmed@example.com",
          role: ["إدارة الطلبات"],
          permissions: {
            "إدارة الطلبات": ["ViewOrders", "UpdateOrderStatus", "PrintInvoices"]
          }
        },
        {
          code: 2,
          name: "احمد محمد",
          email: "ahmed2@example.com",
          role: ["إدارة الطلبات", "إدارة المنتجات"],
          permissions: {
            "إدارة الطلبات": ["ViewOrders", "UpdateOrderStatus"],
            "إدارة المنتجات": ["ViewProducts", "AddProducts", "EditProducts"]
          }
        },
        // More products here
      ],
      isPopupVisible: false,
      popupType: "",
      selectedRow: null,
    };
  },
  computed: {
    filteredRows() {
      return this.rows.filter((row) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (typeof row.name === "string" && row.name.toLowerCase().includes(searchTerm)) ||
          (typeof row.email === "string" && row.email.toLowerCase().includes(searchTerm)) ||
          (Array.isArray(row.role) && row.role.some(role => typeof role === "string" && role.toLowerCase().includes(searchTerm)))
        );
      });
    },
  },
  mounted() {
    this.fetchUserData(); // Fetch user data dynamically
    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }
  },
  methods: {
    fetchUserData() {
      // Simulate fetching user data from an API or store
    },
    openPopup(type, row = null) {
      this.popupType = type;
      this.selectedRow = row
        ? { 
            ...row, 
            role: [...row.role], // Clone the role array
            permissions: row.permissions ? JSON.parse(JSON.stringify(row.permissions)) : {} // Deep clone permissions
          }
        : {
            code:
              this.rows.length > 0
                ? Math.max(...this.rows.map((r) => r.code)) + 1
                : 1,
            name: "",
            email: "",
            role: [],
            permissions: {},
          };
      this.isPopupVisible = true;
    },
    closePopup() {
      this.isPopupVisible = false;
      this.popupType = "";
      this.selectedRow = null;
    },
    handleSave(updatedRow) {
      if (this.popupType === "add") {
        this.rows.push(updatedRow);
      } else if (this.popupType === "edit") {
        const index = this.rows.findIndex(
          (row) => row.code === updatedRow.code
        );
        if (index !== -1) this.rows.splice(index, 1, updatedRow);
      }
      this.closePopup();
    },
    handleDelete(code) {
      this.rows = this.rows.filter((row) => row.code !== code);
      this.closePopup();
    },
  },
};
</script>
