<template>
  <div class="home" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="Control_panel">
      <div class="boxDetails">
        <boxDetails />
      </div>
      <div class="dashboard">
        <div class="summary-container">
          <p>{{ $t("OrderPlanner") }}</p>
          <div class="order-summary">
            <span class="order-count">11,756</span>
            <span class="order-percentage">+23%</span>
          </div>
          <canvas id="orders-chart"></canvas>
          <div class="month-selector">
            <span>Jan</span>
            <span>Feb</span>
            <span class="active">March</span>
            <span>Apr</span>
            <span>May</span>
          </div>
        </div>
        <div class="chart-container">
          <div class="Flex">
            <p>{{ $t("Sales_purchase") }}</p>
            <div class="legend">
              <span><span class="sales-dot"></span> {{ $t("Sales") }}</span>
            </div>
          </div>
          <canvas id="sales-purchases-chart"></canvas>
        </div>
      </div>
      <div class="table-container">
        <div class="headerTable">
          <div class="icon_text">
            <div class="icon">
              <SvgIcon name="resturant"></SvgIcon>
            </div>
            <p>{{ $t("restuarants") }}</p>
          </div>
          <div class="search_add">
            <div class="search">
              <input type="text" v-model="filter" :placeholder="$t('search')" />
              <SvgIcon class="svg" name="search"></SvgIcon>
            </div>
            <button class="search-button" @click="openPopup('add', {})">
              <p class="addRestbtn">{{ $t("AddRest") }}</p>
              <span class="icon">
                <SvgIcon name="add"></SvgIcon>
              </span>
            </button>
          </div>
        </div>
        <LoadingHere :isLoading="isLoading" />

        <div class="table-responsive">
          <table>
            <thead>
              <tr class="table-header">
                <th>
                  <div
                    style="
                      display: flex;
                      align-items: center;
                      margin-right: 10px;
                      gap: 5px;
                    "
                  >
                    <SvgIcon name="circle"></SvgIcon>

                    {{ $t("headTable1") }}
                  </div>
                </th>
                <th>{{ $t("headTable2") }}</th>
                <th>{{ $t("headTable3") }}</th>
                <th>{{ $t("headTable4") }}</th>
                <th>{{ $t("headTable5") }}</th>
                <th>{{ $t("AllProcedures") }}</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="(rows, index) in filteredRows"
                :key="`product-${index}`"
              >
                <td
                  style="
                    display: flex;
                    align-items: center;
                    margin-right: 10px;
                    gap: 5px;
                  "
                >
                  <SvgIcon name="dot_circle"></SvgIcon>
                  {{ rows.id }}
                </td>
                <td>{{ rows.restName }}</td>
                <td>{{ rows.productCount }}</td>
                <td>{{ rows.orderCount }}</td>
                <td>{{ formatDate(rows.lastPurchase) }}</td>
                <td class="actions">
                  <div class="iconsIctions">
                    <div class="icon" @click="openPopup('edit', rows)">
                      <SvgIcon class="svg" name="edit"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('view', rows)">
                      <SvgIcon class="svg" name="view"></SvgIcon>
                    </div>
                    <div class="icon" @click="openPopup('delete', rows)">
                      <SvgIcon class="svg delete" name="deleteItem"></SvgIcon>
                    </div>
                  </div>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>
  <dashboardPopup
    v-if="isPopupVisible"
    :type="popupType"
    :row="selectedRow"
    @close="closePopup"
    @save="handlePopupSave"
  />
</template>

<script>
// @ is an alias to /src
import boxDetails from "@/components/dashboard/boxDetails.vue";
import { Chart } from "chart.js";
import DashboardPopup from "@/components/dashboard/popus/dashboardPopup.vue";
import LoadingHere from "@/components/LoadingHere.vue";
import axios from "axios";
import SvgIcon from "@/components/SvgIcon.vue";

export default {
  name: "dashboardHome",
  components: {
    boxDetails,
    LoadingHere,
    DashboardPopup,
    SvgIcon,
  },

  data() {
    return {
      filter: "",
      rows: [
        // More products here
      ],
      isPopupVisible: false,
      popupType: "",
      selectedRow: {},
      isLoading: false,
      salesChart: null,
      ordersChart: null,
      resizeTimeout: null,
      chartsInitialized: false,
    };
  },
  computed: {
    filteredRows() {
      return this.rows.filter((row) => {
        const searchTerm = this.filter.toLowerCase();
        return (
          (typeof row.restName === "string" &&
            row.restName.toLowerCase().includes(searchTerm)) ||
          (row.id && row.id.toString().toLowerCase().includes(searchTerm))
        );
      });
    },
  },
  async mounted() {
    this.isLoading = true;
    this.fetchUserData(); // Fetch user data dynamically
    this.FetchRows(); // Fetch rows dynamically

    // Wait for DOM to be ready and ensure canvas elements exist
    await this.$nextTick();
    
    // Test Chart.js availability
    if (typeof Chart === 'undefined') {
      console.error('Chart.js is not available. Please check the import.');
      return;
    }
    
    console.log('Chart.js is available:', Chart);
    
    // Add a small delay to ensure DOM is fully rendered
    setTimeout(() => {
      this.initializeCharts();
    }, 100);
    
    // Retry chart initialization if it fails
    setTimeout(() => {
      if (!this.chartsInitialized) {
        console.log('Retrying chart initialization...');
        this.initializeCharts();
      }
    }, 500);
    
    if (this.$toast) {
      this.$toast.success("Welcome to your dashboard!");
    }
    
    // Add resize listener for responsive charts
    window.addEventListener('resize', this.handleResize);
  },
  beforeUnmount() {
    // Clean up charts to prevent memory leaks
    this.destroyCharts();
    
    // Remove resize listener
    window.removeEventListener('resize', this.handleResize);
  },
  methods: {
    destroyCharts() {
      try {
        if (this.salesChart) {
          this.salesChart.destroy();
          this.salesChart = null;
        }
        if (this.ordersChart) {
          this.ordersChart.destroy();
          this.ordersChart = null;
        }
        this.chartsInitialized = false;
      } catch (error) {
        console.error("Error destroying charts:", error);
      }
    },
    initializeCharts() {
      try {
        if (this.chartsInitialized) {
          return;
        }
        
        // Check if Chart is properly imported
        if (typeof Chart === 'undefined') {
          console.error('Chart is not defined. Chart.js may not be properly imported.');
          return;
        }
        
        console.log('Initializing charts...');
        this.renderSalesPurchasesChart();
        this.renderOrdersChart();
        this.chartsInitialized = true;
        console.log('Charts initialized successfully');
      } catch (error) {
        console.error("Error initializing charts:", error);
      }
    },
    handleResize() {
      // Debounce resize events for better performance
      clearTimeout(this.resizeTimeout);
      this.resizeTimeout = setTimeout(() => {
        try {
          if (this.salesChart && this.salesChart.canvas) {
            this.salesChart.resize();
          }
          if (this.ordersChart && this.ordersChart.canvas) {
            this.ordersChart.resize();
          }
        } catch (error) {
          console.error("Error resizing charts:", error);
        }
      }, 250);
    },
    fetchUserData() {
      // Simulate fetching user data from an API or store
    },
    FetchRows() {
      const token = localStorage.getItem("authToken");
      axios
        .get(
          "https://backend.alaqdk.com/api/admin/restaurants",
          {
            headers: {
              "Accept-Language": "ar",
              Authorization: `Bearer ${token}`, // Add the Authorization header
            },
          }
        )
        .then((response) => {
          this.isLoading = false;
          console.log("Restaurant Response:", response.data); // Log the response
          const data = response.data;
          
          // Check if data exists and has the expected structure
          if (data && data.status && data.data && Array.isArray(data.data)) {
            this.rows = data.data
              .filter((item) => item && item.id) // Filter out items without id
              .map((item) => ({
                id: item.id || `restaurant_${Date.now()}_${Math.random()}`,
                restName: item.name || "N/A",
                email: item.email || "",
                phone: item.phone || "",
                productCount: item.total_products || 0,
                orderCount: item.total_orders || 0,
                lastPurchase: item.last_order || "No orders yet",
              }));
            console.log("Processed rows:", this.rows);
          } else {
            console.error("Failed to fetch rows data: Invalid data structure", data);
            this.rows = []; // Set empty array if data is invalid
          }
        })
        .catch((error) => {
          this.isLoading = false; // Set loading state to false
          console.error("Error fetching rows data:", error);
          this.rows = []; // Set empty array on error
        });
    },
    renderSalesPurchasesChart() {
      try {
        const canvas = document.getElementById("sales-purchases-chart");
        if (!canvas) {
          console.warn("Sales chart canvas not found");
          return;
        }
        
        console.log('Sales chart canvas found:', canvas);
        
        // Destroy existing chart if it exists
        if (this.salesChart) {
          this.salesChart.destroy();
          this.salesChart = null;
        }
        
        const ctx = canvas.getContext("2d");
        if (!ctx) {
          console.error("Could not get 2D context for sales chart");
          // Try to force canvas dimensions and retry
          canvas.width = canvas.offsetWidth || 400;
          canvas.height = canvas.offsetHeight || 200;
          const retryCtx = canvas.getContext("2d");
          if (!retryCtx) {
            console.error("Still could not get 2D context for sales chart after retry");
            return;
          }
          console.log('Sales chart context obtained on retry:', retryCtx);
        } else {
          console.log('Sales chart context obtained:', ctx);
        }
        
        // Ensure canvas has proper dimensions
        if (canvas.width === 0 || canvas.height === 0) {
          canvas.width = canvas.offsetWidth || 400;
          canvas.height = canvas.offsetHeight || 200;
          console.log('Set canvas dimensions:', canvas.width, 'x', canvas.height);
        }
        
        // Additional check to ensure canvas is properly sized
        if (canvas.offsetWidth === 0 || canvas.offsetHeight === 0) {
          console.warn('Canvas has zero offset dimensions, setting default size');
          canvas.style.width = '400px';
          canvas.style.height = '200px';
          canvas.width = 400;
          canvas.height = 200;
        }
        
        this.salesChart = new Chart(ctx, {
          type: "line",
          data: {
            labels: [
              "1 Oct",
              "3 Oct",
              "7 Oct",
              "10 Oct",
              "14 Oct",
              "20 Oct",
              "23 Oct",
              "27 Oct",
              "30 Oct",
            ],
            datasets: [
              {
                label: "المبيعات",
                data: [1200, 2000, 1800, 1300, 3000, 2500, 180, 1200, 3000],
                borderColor: "#800080",
                borderWidth: 3,
                tension: 0.4,
                pointRadius: 6,
                pointHoverRadius: 8,
                pointBackgroundColor: "#800080",
                pointBorderColor: "#ffffff",
                pointBorderWidth: 2,
                pointHoverBackgroundColor: "#800080",
                pointHoverBorderColor: "#ffffff",
                pointHoverBorderWidth: 3,
                backgroundColor: "rgba(128, 0, 128, 0.1)",
                fill: true,
              },
              {
                label: "المشتريات",
                data: [200, 1000, 1200, 900, 2500, 2800, 180, 1500, 1800],
                borderColor: "#D87093",
                borderWidth: 3,
                tension: 0.4,
                pointRadius: 6,
                pointHoverRadius: 8,
                pointBackgroundColor: "#D87093",
                pointBorderColor: "#ffffff",
                pointBorderWidth: 2,
                pointHoverBackgroundColor: "#D87093",
                pointHoverBorderColor: "#ffffff",
                pointHoverBorderWidth: 3,
                backgroundColor: "rgba(216, 112, 147, 0.1)",
                fill: true,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: {
              intersect: false,
              mode: 'index',
            },
            animation: {
              duration: 1500,
              easing: 'easeInOutQuart',
            },
            scales: {
              x: {
                grid: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.1)',
                  lineWidth: 1,
                },
                ticks: {
                  color: '#666',
                  font: {
                    size: 12,
                    weight: '500'
                  },
                  padding: 8
                },
                border: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.2)',
                  width: 1
                }
              },
              y: {
                beginAtZero: true,
                max: 3500,
                grid: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.1)',
                  lineWidth: 1,
                  drawBorder: false,
                },
                ticks: {
                  color: '#666',
                  font: {
                    size: 12,
                    weight: '500'
                  },
                  padding: 8,
                  callback: function(value) {
                    return value.toLocaleString();
                  }
                },
                border: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.2)',
                  width: 1
                }
              },
            },
            plugins: {
              legend: {
                display: false,
              },
              tooltip: {
                backgroundColor: 'rgba(0, 0, 0, 0.8)',
                titleColor: '#fff',
                bodyColor: '#fff',
                borderColor: 'rgba(255, 255, 255, 0.2)',
                borderWidth: 1,
                cornerRadius: 8,
                displayColors: true,
                titleFont: {
                  size: 14,
                  weight: 'bold'
                },
                bodyFont: {
                  size: 13
                },
                padding: 12,
                callbacks: {
                  label: function(context) {
                    let label = context.dataset.label || '';
                    if (label) {
                      label += ': ';
                    }
                    if (context.parsed.y !== null) {
                      label += context.parsed.y.toLocaleString();
                    }
                    return label;
                  }
                }
              },
              title: {
                display: false
              }
            },
            elements: {
              line: {
                borderWidth: 3
              },
              point: {
                hoverRadius: 8,
                radius: 6
              }
            }
          },
        });
      } catch (error) {
        console.error("Error rendering sales chart:", error);
      }
    },
    renderOrdersChart() {
      try {
        const canvas = document.getElementById("orders-chart");
        if (!canvas) {
          console.warn("Orders chart canvas not found");
          return;
        }
        
        console.log('Orders chart canvas found:', canvas);
        
        // Destroy existing chart if it exists
        if (this.ordersChart) {
          this.ordersChart.destroy();
          this.ordersChart = null;
        }
        
        const ctx = canvas.getContext("2d");
        if (!ctx) {
          console.error("Could not get 2D context for orders chart");
          // Try to force canvas dimensions and retry
          canvas.width = canvas.offsetWidth || 400;
          canvas.height = canvas.offsetHeight || 150;
          const retryCtx = canvas.getContext("2d");
          if (!retryCtx) {
            console.error("Still could not get 2D context for orders chart after retry");
            return;
          }
          console.log('Orders chart context obtained on retry:', retryCtx);
        } else {
          console.log('Orders chart context obtained:', ctx);
        }
        
        // Ensure canvas has proper dimensions
        if (canvas.width === 0 || canvas.height === 0) {
          canvas.width = canvas.offsetWidth || 400;
          canvas.height = canvas.offsetHeight || 150;
          console.log('Set orders canvas dimensions:', canvas.width, 'x', canvas.height);
        }
        
        // Additional check to ensure canvas is properly sized
        if (canvas.offsetWidth === 0 || canvas.offsetHeight === 0) {
          console.warn('Orders canvas has zero offset dimensions, setting default size');
          canvas.style.width = '400px';
          canvas.style.height = '150px';
          canvas.width = 400;
          canvas.height = 150;
        }
        
        this.ordersChart = new Chart(ctx, {
          type: "line",
          data: {
            labels: ["Jan", "Feb", "March", "Apr", "May"],
            datasets: [
              {
                label: "Orders",
                data: [10000, 11000, 11756, 10500, 11200],
                borderColor: "#D87093",
                borderWidth: 3,
                fill: true,
                backgroundColor: "rgba(216, 112, 147, 0.3)",
                tension: 0.4,
                pointRadius: 6,
                pointHoverRadius: 8,
                pointBackgroundColor: "#800080",
                pointBorderColor: "#ffffff",
                pointBorderWidth: 2,
                pointHoverBackgroundColor: "#800080",
                pointHoverBorderColor: "#ffffff",
                pointHoverBorderWidth: 3,
              },
            ],
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: {
              intersect: false,
              mode: 'index',
            },
            animation: {
              duration: 1500,
              easing: 'easeInOutQuart',
            },
            scales: {
              x: {
                grid: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.1)',
                  lineWidth: 1,
                },
                ticks: {
                  color: '#666',
                  font: {
                    size: 12,
                    weight: '500'
                  },
                  padding: 8
                },
                border: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.2)',
                  width: 1
                }
              },
              y: {
                beginAtZero: true,
                grid: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.1)',
                  lineWidth: 1,
                  drawBorder: false,
                },
                ticks: {
                  color: '#666',
                  font: {
                    size: 12,
                    weight: '500'
                  },
                  padding: 8,
                  callback: function(value) {
                    return value.toLocaleString();
                  }
                },
                border: {
                  display: true,
                  color: 'rgba(0, 0, 0, 0.2)',
                  width: 1
                }
              },
            },
            plugins: {
              legend: {
                display: false,
              },
              tooltip: {
                backgroundColor: 'rgba(0, 0, 0, 0.8)',
                titleColor: '#fff',
                bodyColor: '#fff',
                borderColor: 'rgba(255, 255, 255, 0.2)',
                borderWidth: 1,
                cornerRadius: 8,
                displayColors: true,
                titleFont: {
                  size: 14,
                  weight: 'bold'
                },
                bodyFont: {
                  size: 13
                },
                padding: 12,
                callbacks: {
                  label: function(context) {
                    let label = context.dataset.label || '';
                    if (label) {
                      label += ': ';
                    }
                    if (context.parsed.y !== null) {
                      label += context.parsed.y.toLocaleString();
                    }
                    return label;
                  }
                }
              },
              title: {
                display: false
              }
            },
            elements: {
              line: {
                borderWidth: 3
              },
              point: {
                hoverRadius: 8,
                radius: 6
              }
            }
          },
        });
      } catch (error) {
        console.error("Error rendering orders chart:", error);
      }
    },
    openPopup(type, row) {
      this.popupType = type;
      this.selectedRow = { ...row };
      this.isPopupVisible = true;
    },
    closePopup() {
      this.isPopupVisible = false;
      this.popupType = ""; // Reset popup type
      this.selectedRow = null; // Reset selected row
    },
    handlePopupSave(updatedRow) {
      this.saveChanges(updatedRow); // Call saveChanges when popup emits save
    },
    saveChanges(updatedRow) {
      if (this.popupType === "add") {
        updatedRow.id = Date.now(); // Ensure a unique ID for new rows
        this.rows.push(updatedRow);
      } else if (this.popupType === "edit") {
        const index = this.rows.findIndex((row) => row.id === updatedRow.id);
        if (index !== -1) {
          this.rows.splice(index, 1, updatedRow);
        }
      } else if (this.popupType === "delete") {
        this.rows = this.rows.filter((row) => row.id !== updatedRow.id);
      }
      this.closePopup();
    },
    formatDate(dateString) {
      if (!dateString || dateString === "N/A") {
        return "N/A";
      }
      
      try {
        const date = new Date(dateString);
        
        // Check if date is valid
        if (isNaN(date.getTime())) {
          return "Invalid Date";
        }
        
        // Compact date format - always use Gregorian calendar
        const options = {
          year: '2-digit',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          calendar: 'gregory' // Force Gregorian calendar
        };
        
        return date.toLocaleDateString(this.$i18n.locale === 'ar' ? 'ar-SA-u-ca-gregory' : 'en-US', options);
      } catch (error) {
        console.error('Error formatting date:', error);
        return dateString;
      }
    },
  },
};
</script>
<style lang="scss" scoped>
