  width: calc(100% - 285px);
  max-width: 100%;
  padding: 0 20px;
  box-sizing: border-box;
  
  /* Responsive margins for sidebar */
  @media (min-width: 1200px) {
    margin-left: 284px; /* Width of sidebar */
    
    /* RTL support */
    [dir="rtl"] & {
      margin-left: 0;
      margin-right: 284px;
    }
  }
  
  @media (min-width: 992px) and (max-width: 1199px) {
    margin-left: 285px;
    
    [dir="rtl"] & {
      margin-left: 0;
      margin-right: 285px;
    }
  }
  
  @media (max-width: 991px) {
    margin-left: 0;
    margin-right: 0;
    padding: 0 15px;
  }
}

