    margin-left: 10px; /* Width of sidebar */
    
    /* RTL support */
    [dir="rtl"] & {
      margin-left: 0;
      margin-right: 10px;
    }
  }
  @media (max-width: 768px) {
    flex-direction: column;
    gap: 15px;
  }
}

.dashboard {
  width: 100%;
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  box-sizing: border-box;
  @media (min-width: 1200px) {
    margin-left: 10px; /* Width of sidebar */
    
    /* RTL support */
    [dir="rtl"] & {
      margin-left: 0;
      margin-right: 10px;
    }
  }
  @media (min-width: 768px) {
    flex-direction: row;
  }
  
  @media (max-width: 767px) {
    flex-direction: column;
    gap: 15px;
  }
}

.chart-container,
.summary-container {
  background: #fff;
  border-radius: 12px;
  padding: 20px;
  background-color: rgba(255, 255, 255, 1);
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(0, 0, 0, 0.05);
  transition: all 0.3s ease;
  min-height: 300px;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  max-width: 100%;
  
  p {
    margin: 0 0 15px 0;
    font-size: 16px;
    font-weight: 700;
    line-height: 18px;
    color: #000000;
  }
}

.summary-container {
  flex: 1;
  min-width: 300px;
  max-width: 400px;
  width: 100%;
  
  @media (max-width: 767px) {
    min-width: 100%;
    max-width: 100%;
  }
}

.chart-container {
  flex: 2;
  min-width: 400px;
  width: 100%;
  
  @media (max-width: 767px) {
    min-width: 100%;
    flex: 1;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .summary-container {
    min-width: 250px;
    max-width: 300px;
    width: 100%;
  }
  
  .chart-container {
    min-width: 350px;
    width: 100%;
    
    .Flex p {
      font-size: 14px;
    }
    
    .legend span {
      font-size: 13px;
    }
  }
}
.Flex {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.legend {
