/* Custom Toggle Switch for 24x14px */
.switch {
  position: relative;
  display: inline-block;
  width: 24px;
  height: 14px;
  top: 5px;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: #ccc;
  opacity: 1;
  border-radius: 100px;
  transition: background 0.3s;
}

.slider:before {
  position: absolute;
  content: "";
  height: 12px;
  width: 12px;
  left: 1px;
  bottom: 1px;
  background: #fff;
  transition: 0.3s;
  border-radius: 50%;
}

input:checked + .slider {
  background: #3FAD4C;
}

input:checked + .slider:before {
  transform: translateX(10px);
}
